from pathlib import Path
import re, sys
r=Path(sys.argv[1])

def rw(rel, fn):
 p=r/rel; p.write_text(fn(p.read_text()))

rw('android/app/build.gradle',lambda s:s.replace('versionCode 13','versionCode 14').replace("versionName '2.3.1'","versionName '2.3.2'"))

def html(s):
 s=s.replace('        <span class="muted small">halka arzdan beri</span>\n','')
 s=s.replace('          <strong id="dailyProfit">₺0,00</strong>\n          <small id="dailyPct">%0,00</small>','          <div class="metric-value-row"><strong id="dailyProfit">₺0,00</strong><span id="dailyPct" class="metric-inline-value">%0,00</span></div>')
 for x in ('          <small>ilk maliyet</small>\n','          <small>eldeki hisseler</small>\n','          <small>gerçekleşen satış</small>\n','      <p class="chart-help">Grafiğe dokun: gün, portföy büyüklüğü ve kâr/zararı gör.</p>\n','        <span class="muted small">en yeni üstte</span>\n','        <span class="muted small">aktif değer</span>\n','        <p>Yalnızca BIST kodunu ve lot sayısını girin. Halka arz fiyatı, tarih ve güncel fiyat otomatik bulunur.</p>\n','          <p>Yaklaşan, talepte olan ve son tamamlanan halka arzları tek ekranda takip edin.</p>\n','          <p>Tavan serisi, halka arz sonuçları ve şirket/arz detaylarını ayrı bir çalışma alanında inceleyin.</p>\n','            <p>Hisse ve toplam portföy, önceki BIST kapanışına göre eşik katlarına ulaştığında bildirilir.</p>\n'): s=s.replace(x,'')
 s=s.replace('Takvim bu sekmeye ilk girişte otomatik yüklenir.','Henüz veri yok.').replace('Gelişmiş özellikler hazırlanıyor…','Hazırlanıyor…').replace('v2.3.1 • Build 13','v2.3.2 • Build 14')
 if 'id="notificationIntro"' not in s:
  m='  <nav id="bottomNav" class="bottom-nav" aria-label="Ana menü">'
  q='''  <div id="notificationIntro" class="notification-intro" hidden>\n    <section class="notification-intro-card" role="dialog" aria-modal="true" aria-labelledby="notificationIntroTitle">\n      <div class="notification-intro-icon" aria-hidden="true">◉</div>\n      <h2 id="notificationIntroTitle">Bildirimleri açalım mı?</h2>\n      <div class="notification-intro-actions">\n        <button id="notificationIntroLater" class="secondary-btn" type="button">Şimdi değil</button>\n        <button id="notificationIntroAllow" class="primary-btn" type="button">Bildirimleri aç</button>\n      </div>\n    </section>\n  </div>\n\n'''
  s=s.replace(m,q+m)
 return s
rw('android/app/src/main/assets/www/index.html',html)

def js(s):
 s=s.replace("const proAccess = createProAccess(globalThis.localStorage);","const proAccess = createProAccess(globalThis.localStorage);\nconst NOTIFICATION_INTRO_KEY = 'notification_intro_seen_v1';")
 n="function readNativeNotificationPermission() {\n  try { return window.AndroidBridge?.getNotificationPermissionStatus?.() || 'unsupported'; }\n  catch { return 'unsupported'; }\n}\n"
 a=n+"\nfunction hideNotificationIntro() {\n  const intro = $('#notificationIntro');\n  if (intro) intro.hidden = true;\n}\n\nfunction maybeShowNotificationIntro() {\n  if (readNativeNotificationPermission() !== 'prompt') return;\n  if (safeGetLocal(NOTIFICATION_INTRO_KEY) === '1') return;\n  const intro = $('#notificationIntro');\n  if (intro) intro.hidden = false;\n}\n\nfunction rememberNotificationIntro() {\n  safeSetLocal(NOTIFICATION_INTRO_KEY, '1');\n  hideNotificationIntro();\n}\n"
 if 'function maybeShowNotificationIntro()' not in s:s=s.replace(n,a)
 s=s.replace("window.__notificationPermissionChanged = () => renderSettings();","window.__notificationPermissionChanged = () => { hideNotificationIntro(); renderSettings(); };")
 s=s.replace('Sektör bilgileri arka planda bir kez yüklenir. Gerekirse hisse detayından elle düzeltebilirsiniz.','Henüz veri yok.')
 s=s.replace('Geçmiş fiyat verisi yüklendiğinde gün gün değişim burada görünecek.','Henüz veri yok.')
 l="$('#requestNotificationPermission')?.addEventListener('click', () => {\n  try { window.AndroidBridge?.requestNotificationPermission?.(); } catch {}\n  setTimeout(renderSettings, 400);\n});\n"
 if "$('#notificationIntroAllow')" not in s:s=s.replace(l,l+"$('#notificationIntroLater')?.addEventListener('click', () => rememberNotificationIntro());\n$('#notificationIntroAllow')?.addEventListener('click', () => {\n  rememberNotificationIntro();\n  try { window.AndroidBridge?.requestNotificationPermission?.(); } catch {}\n});\n")
 s=s.replace('loadPortfolio();\nsetTimeout(() => refreshBackgroundHistory(), 900);','loadPortfolio();\nsetTimeout(maybeShowNotificationIntro, 450);\nsetTimeout(() => refreshBackgroundHistory(), 900);')
 return s
rw('android/app/src/main/assets/www/app.js',js)

css='''\n/* v2.3.2 glass refresh */\n:root{\n  --glass-border:rgba(148,190,255,.22);\n  --glass-highlight:rgba(205,229,255,.20);\n  --glass-deep:rgba(8,18,39,.70);\n}\nbody{\n  background:\n    radial-gradient(720px 420px at 18% -8%,rgba(42,111,255,.18),transparent 68%),\n    radial-gradient(640px 380px at 92% 18%,rgba(31,111,255,.12),transparent 70%),\n    linear-gradient(180deg,#06101f 0%,#050a13 54%,#040812 100%);\n}\n.hero-card,.chart-card,.analytics-card,.holding-card,.settings-card,.view-hero,.calendar-card,.bottom-nav,.icon-btn,.market-status{\n  border-color:var(--glass-border);\n  background:linear-gradient(145deg,rgba(29,61,116,.34),rgba(10,23,47,.72) 45%,rgba(7,15,31,.82));\n  backdrop-filter:blur(20px) saturate(135%);\n  -webkit-backdrop-filter:blur(20px) saturate(135%);\n  box-shadow:inset 0 1px 0 rgba(255,255,255,.12),inset 0 -1px 0 rgba(66,139,255,.08),0 18px 56px rgba(0,20,58,.30);\n}\n.hero-card,.chart-card,.analytics-card,.holding-card,.settings-card,.view-hero,.calendar-card,.bottom-nav{position:relative;overflow:hidden}\n.hero-card::after,.chart-card::after,.analytics-card::after,.holding-card::after,.settings-card::after,.view-hero::after,.calendar-card::after,.bottom-nav::after{content:"";position:absolute;pointer-events:none;z-index:0;top:-55%;left:-42%;width:38%;height:210%;transform:rotate(18deg) translateX(-180%);background:linear-gradient(90deg,transparent,rgba(208,231,255,.03),rgba(206,232,255,.20),rgba(123,183,255,.08),transparent);filter:blur(1px);animation:glassSheen 9s ease-in-out infinite}\n.hero-card>* ,.chart-card>* ,.analytics-card>* ,.holding-card>* ,.settings-card>* ,.view-hero>* ,.calendar-card>* ,.bottom-nav>*{position:relative;z-index:1}\n.hero-card::before{width:290px;height:210px;right:-90px;top:-70px;border-radius:44%;background:radial-gradient(circle at 38% 40%,rgba(74,151,255,.30),rgba(37,90,220,.10) 46%,transparent 72%);filter:blur(10px)}\n.icon-btn,.market-status{box-shadow:inset 0 1px 0 rgba(255,255,255,.14),0 8px 26px rgba(0,26,70,.22)}\n.metric-value-row{display:flex;align-items:baseline;gap:7px;min-width:0}\n.metric-inline-value{font-size:10px;font-weight:750;color:#8ea4c8;white-space:nowrap}\n.notification-intro{position:fixed;inset:0;z-index:90;display:grid;place-items:center;padding:24px;background:rgba(2,8,18,.58);backdrop-filter:blur(12px);-webkit-backdrop-filter:blur(12px)}\n.notification-intro[hidden]{display:none}\n.notification-intro-card{width:min(100%,360px);padding:24px;border:1px solid rgba(148,190,255,.26);border-radius:26px;background:linear-gradient(150deg,rgba(28,59,111,.78),rgba(7,18,39,.92));box-shadow:inset 0 1px 0 rgba(255,255,255,.15),0 28px 80px rgba(0,8,28,.58);text-align:center}\n.notification-intro-icon{width:48px;height:48px;display:grid;place-items:center;margin:0 auto 12px;border-radius:16px;background:rgba(93,143,255,.14);border:1px solid rgba(130,178,255,.22);color:#8fc8ff;font-size:24px;box-shadow:inset 0 1px 0 rgba(255,255,255,.10)}\n.notification-intro-card h2{font-size:22px;margin:0 0 20px}\n.notification-intro-actions{display:grid;grid-template-columns:1fr 1.15fr;gap:9px}\n.notification-intro-actions .primary-btn,.notification-intro-actions .secondary-btn{min-height:48px}\n@keyframes glassSheen{0%,58%,100%{transform:rotate(18deg) translateX(-190%);opacity:0}64%{opacity:.85}76%{transform:rotate(18deg) translateX(470%);opacity:.12}77%{opacity:0}}\n@media(prefers-reduced-motion:reduce){.hero-card::after,.chart-card::after,.analytics-card::after,.holding-card::after,.settings-card::after,.view-hero::after,.calendar-card::after,.bottom-nav::after{animation:none;display:none}}\nhtml[data-theme="light"] .notification-intro{background:rgba(220,228,244,.58)}\nhtml[data-theme="light"] .notification-intro-card{background:linear-gradient(150deg,rgba(255,255,255,.98),rgba(242,247,255,.98));border-color:rgba(74,113,180,.18);box-shadow:0 28px 70px rgba(41,57,83,.20)}\n'''
def style(s):
 return s+css if '/* v2.3.2 glass refresh */' not in s else s
rw('android/app/src/main/assets/www/styles.css',style)
